export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "午前一時五十八分。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ロビーの明かりは半分しか点いていなかった。管理人のカウンターは空っぽで、椅子の背には色あせたジャンパーが掛けてある。消し忘れのラジオが、ごく小さな音で古い歌を流していた。隣の部屋で誰かが独り言をつぶやいているみたいに。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "天井の蛍光灯はずっとジーッと鳴っていて、一瞬ちらついては、また持ちこたえる。郵便受けの壁には排水管修理や引っ越し業者のステッカーがびっしり貼られ、一枚の上にまた一枚と重なって、まるでこの建物の年輪のようだった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）築四十年のビル。蛍光灯もたぶん四十年もの。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "着いた？", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "方芮の声は九階から届いた。何層ものコンクリートと一台のスマホを隔てているせいか、いつもより遠く聞こえる。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "着いた。誰もいない。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "当たり前でしょ。夜中の二時にロビーにいる人なんかいないって。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "電話の向こうで、布団のこすれるカサカサという音がした。許念には彼女の姿がほとんど見えるようだった——リビングの中古のソファで丸くなり、クッションを抱きしめて、怖がりながらもわくわくしている。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）言い出しっぺは布団の中。実行役はロビー。実に公平だ。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ことの始まりは夜の十一時だった。期末レポートが半分まで進んだところで、ふたりとももう手を動かす気になれず、方芮がスマホをスクロールしていて、ある記事に行き当たった。タイトルは「エレベーターゲーム、やってみた」。下には数百件のコメントがつき、半分は「ヤラセ」、半分は「やめとけ」と言っていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "なんにも怖くないって言ってたじゃん？", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "幽霊は怖くないって言ったの。怖いのは期末レポート。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "じゃあちょうどいいじゃん。これやって帰ってきたら、レポートなんか怖くなくなるよ。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "すらすらとした口ぶりだった。まるで、下のコンビニに夜食を買いに行く話でもするみたいに。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）本当は、眠れないだけ。三時に寝ても五時に寝ても、違うのは天井を二時間よけいに眺めるかどうかだけ。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "許念は上りのボタンを押した。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "階数表示は古い型の赤いデジタル数字で、八から下へと数を減らしていく。一つ変わるたびに、いちいちためらうような間があった。昇降路の中をケーブルが引きずられていく音は長く、重く、壁の中で何かが寝返りを打っているようだった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "もう一回ルール読むね。一つ目、ひとりで乗ること。途中で誰か乗ってこようとしたら、降りて、別の日にやり直し。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "二つ目、四、二、六、二、十の順に押す。どの階でも降りちゃだめ。ドアが閉まってから次のボタンを押すこと。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "三つ目、十階に着いたら五を押す。五階で、女の人が乗ってくるかもしれない。話しかけちゃだめ。顔を見ちゃだめ。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "向こうから話しかけてきたら？", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "……書いてない。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）実に頼もしい。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "四つ目、その人が乗ってきたら一を押す。エレベーターが下に行ったら失敗。帰って寝る。もし、上に行ったら——", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "方芮はそこで少し言葉を切った。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "十階に着いたら、ボタンはもう反応しなくなる。戻りたければ、押せるのは一だけ。それも一回だけ。最後のルールはこう。もし外に出たら、振り返っちゃだめ。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "チン。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ドアが左右に開く。左側の扉はいつも半拍遅れる。足の悪い老人のように。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "（心の声）おばあちゃんは言っていた。夜中に鏡を見てはいけない。名前を呼ばれても、振り返って返事をしてはいけない。エレベーターのことは、おばあちゃんも何も言っていなかった。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "念念。電話、切らないでね。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "許念は中へ足を踏み入れた。", background: Background.Root_Act1_S0 },
];
